//
// Returning phone numbers needs a new contract version (for example
// customers.lookup@2 with an optional `phone` field) and its own handler.
// Version 1 must keep its exact existing shape.
export async function lookupCustomer(input) {
  const row = readExport().find((r) => r.cust_id === input.customerId);
  if (!row) {
    throw errors.notFound(`no customer ${input.customerId}`);
  }
  return {
    customerId: row.cust_id,
    name: row.full_name,
    email: row.mail,
    tier: TIERS[row.level],
    since: row.created
  };
}
